## Libraries


::: {.cell}

```{.r .cell-code}
library(readxl)

# Graph 1
library(dplyr)
library(ggplot2)

# Graph 2
library(gt)
library(gtExtras)
library(tidyverse)
library(glue)

# Graph 3
library(tidyverse)
library(patchwork) 
```
:::


## File


::: {.cell}

```{.r .cell-code}
hpi_raw <- read_excel(here::here("files/Happy-Planet-Index-2006-2025-public-data-set.xlsx"), 
                        sheet = "All Data", skip = 1)
```
:::


## Data Check


::: {.cell}

```{.r .cell-code}
hpi <- hpi_raw[, !names(hpi_raw) %in% c("...15", "...21", "...22", "...23")]
hpi_year <- hpi[hpi$Year == 2025, ]

# Note from data file
continent_map <- c(
  "1" = "Latin America",
  "2" = "North America & Oceania",
  "3" = "Western Europe",
  "4" = "Middle East",
  "5" = "Africa",
  "6" = "South Asia",
  "7" = "Eastern Europe & Central Asia",
  "8" = "East Asia"
)

hpi_year$Continent_name <- factor(continent_map[as.character(hpi_year$Continent)])
```
:::


------------------------------------------------------------------------

# Solbee Kim

## Chart 1. Variable-width column

*Data setup*


::: {.cell}

```{.r .cell-code}
chart1_data <- hpi_year %>%
  group_by(Continent_name) %>%
  summarise(
    total_pop = sum(Population, na.rm = TRUE),
    mean_hpi  = mean(HPI, na.rm = TRUE)
  ) %>%
  arrange(desc(mean_hpi)) %>%
  mutate(
    xmax = cumsum(total_pop),
    xmin = xmax - total_pop,
    xmid = (xmin + xmax) / 2
  )
```
:::


*Plotting*


::: {.cell}

```{.r .cell-code}
rainbow <- c("#FFADAD", "#FFC6FF", "#F0E68C", "#CAFCCF", 
             "#9BF6FF", "#A0C4FF", "#BDB2FF", "#FFD6A5")

ggplot(chart1_data) +
  geom_rect(aes(xmin = xmin, xmax = xmax, ymin = 0, ymax = mean_hpi,
                fill = Continent_name),
            color = "white", linewidth = 0.5) +
  geom_text(aes(x = xmid, y = mean_hpi + 2, label = round(mean_hpi, 1)),
          size = 3.0, fontface = "italic") +
  scale_fill_manual(values = rainbow, name = "Region") +
  scale_x_continuous(labels = scales::comma) +
  scale_y_continuous(limits = c(0, 65), expand = c(0, 0)) +
  labs(
    title = "No link between population and wellbeing",
    x = "Cumulative population",
    y = "Mean of HPI Score",
    caption = "*Source: Happy Planet Index 2025, Hot or Cool Institute"
  ) +
  theme_minimal(base_size = 12) +
  theme(legend.position = "right",
        panel.grid.minor = element_blank(),
        plot.margin = margin(t = 10, r = 10, b = 10, l = 10),
        plot.title = element_text(hjust = 0.5, face = "bold"),
        plot.caption = element_text(hjust = 1),
        plot.title.position = "plot",
        plot.caption.position = "plot",
        axis.title.x = element_text(margin = margin(t = 10)),
        axis.title.y = element_text(margin = margin(r = 10)))
```

